<?php
declare(strict_types=1);
namespace App\Modules\Tourism\Models;
use App\Core\Database;
final class TourismStay{private Database $db;public function __construct(){$this->db=app()->get('db');}public function all(int $t,bool $deleted=false):array{$w=$deleted?'s.deleted_at IS NOT NULL':'s.deleted_at IS NULL';return $this->db->fetchAll("SELECT s.*,p.provider_type,b.name provider_name,d.name destination_name,(SELECT COUNT(*) FROM tourism_stay_room_types r WHERE r.stay_id=s.id AND r.tenant_id=s.tenant_id AND r.deleted_at IS NULL) room_count FROM tourism_stays s INNER JOIN tourism_providers p ON p.id=s.provider_id AND p.tenant_id=s.tenant_id INNER JOIN businesses b ON b.id=p.business_id AND b.tenant_id=p.tenant_id LEFT JOIN tourism_destinations d ON d.id=s.destination_id AND d.tenant_id=s.tenant_id WHERE s.tenant_id=? AND {$w} ORDER BY s.id DESC",[$t]);}public function find(int $t,int $id,bool $deleted=false):?array{$w=$deleted?'s.deleted_at IS NOT NULL':'s.deleted_at IS NULL';return $this->db->fetch("SELECT s.*,p.provider_type,b.name provider_name,d.name destination_name FROM tourism_stays s INNER JOIN tourism_providers p ON p.id=s.provider_id AND p.tenant_id=s.tenant_id INNER JOIN businesses b ON b.id=p.business_id AND b.tenant_id=p.tenant_id LEFT JOIN tourism_destinations d ON d.id=s.destination_id AND d.tenant_id=s.tenant_id WHERE s.tenant_id=? AND s.id=? AND {$w} LIMIT 1",[$t,$id]);}public function create(int $t,array $d,int $u):int{$this->db->execute("INSERT INTO tourism_stays(uuid,tenant_id,provider_id,destination_id,name,slug,stay_type,description,phone,email,address,city,district,state,postal_code,latitude,longitude,check_in_time,check_out_time,amenities,starting_price_per_night,logo_path,cover_image_path,status,created_by,updated_by) VALUES(UUID(),?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",[$t,$d['provider_id'],$d['destination_id'],$d['name'],$d['slug'],$d['stay_type'],$d['description'],$d['phone'],$d['email'],$d['address'],$d['city'],$d['district'],$d['state'],$d['postal_code'],$d['latitude'],$d['longitude'],$d['check_in_time'],$d['check_out_time'],$d['amenities'],$d['starting_price_per_night'],$d['logo_path'],$d['cover_image_path'],$d['status'],$u,$u]);return (int)$this->db->lastInsertId();}public function update(int $t,int $id,array $d,int $u):void{$this->db->execute("UPDATE tourism_stays SET provider_id=?,destination_id=?,name=?,slug=?,stay_type=?,description=?,phone=?,email=?,address=?,city=?,district=?,state=?,postal_code=?,latitude=?,longitude=?,check_in_time=?,check_out_time=?,amenities=?,starting_price_per_night=?,logo_path=?,cover_image_path=?,status=?,updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$d['provider_id'],$d['destination_id'],$d['name'],$d['slug'],$d['stay_type'],$d['description'],$d['phone'],$d['email'],$d['address'],$d['city'],$d['district'],$d['state'],$d['postal_code'],$d['latitude'],$d['longitude'],$d['check_in_time'],$d['check_out_time'],$d['amenities'],$d['starting_price_per_night'],$d['logo_path'],$d['cover_image_path'],$d['status'],$u,$t,$id]);}public function delete(int $t,int $id,int $u):void{$this->db->execute("UPDATE tourism_stays SET deleted_at=NOW(),updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$u,$t,$id]);}public function restore(int $t,int $id,int $u):void{$this->db->execute("UPDATE tourism_stays SET deleted_at=NULL,updated_by=? WHERE tenant_id=? AND id=?",[$u,$t,$id]);}public function nameExists(int $t,string $n,?int $ignore=null):bool{$sql="SELECT id FROM tourism_stays WHERE tenant_id=? AND name=? AND deleted_at IS NULL";$p=[$t,$n];if($ignore!==null){$sql.=" AND id<>?";$p[]=$ignore;}return $this->db->fetch($sql.' LIMIT 1',$p)!==null;}public function slugExists(int $t,string $s,?int $ignore=null):bool{$sql="SELECT id FROM tourism_stays WHERE tenant_id=? AND slug=? AND deleted_at IS NULL";$p=[$t,$s];if($ignore!==null){$sql.=" AND id<>?";$p[]=$ignore;}return $this->db->fetch($sql.' LIMIT 1',$p)!==null;}public function rooms(int $t,int $id,bool $deleted=false):array{$w=$deleted?'deleted_at IS NOT NULL':'deleted_at IS NULL';return $this->db->fetchAll("SELECT * FROM tourism_stay_room_types WHERE tenant_id=? AND stay_id=? AND {$w} ORDER BY id DESC",[$t,$id]);}}
